import numpy as np

N = 5
# random complex sequence
x = np.random.randn(N) + 1j*np.random.randn(N)

# DFT coefficients
X = np.fft.fft(x)  # X[k] = sum_n x[n] e^{-j 2pi k n / N}

# We want y = Phi b, i.e. x = Phi @ X
# So Phi = ifft matrix. Check: x[n] = (1/N) sum_k X[k] e^{j 2pi k n / N}
Phi = np.zeros((N,N), dtype=complex)
for i in range(N):
    for l in range(N):
        Phi[i,l] = (1/N)*np.exp(1j*2*np.pi*l*i/N)

recon = Phi @ X
print("x        =", x)
print("recon    =", recon)
print("max err  =", np.max(np.abs(recon - x)))

# Also verify the DFT matrix itself: X = F x with F[i,l] = e^{-j 2pi i l / N}
F = np.zeros((N,N), dtype=complex)
for i in range(N):
    for l in range(N):
        F[i,l] = np.exp(-1j*2*np.pi*i*l/N)
print("F @ x == X ?", np.allclose(F @ x, X))
print("Phi @ F == I ?", np.allclose(Phi @ F, np.eye(N)))
